.threeui-page-button-stage--attune {
  background: #070709;
}
.threeui-page-button-stage--attune::before {
  background: radial-gradient(circle at 50% 50%, rgba(255, 122, 20, .12), transparent 32%);
}
.threeui-page-button--attune {
  gap: 10px;
